// Attached flows share their parent's frame; they have extent and material,
// not an independent gravitating mass or Kepler orbit.
const choices={diskStyle:[['thermal','Thermal plasma'],['hydrogen','Hydrogen-rich glow'],['helium','Helium-rich glow'],['dust','Cool dust'],['nebula','Nebulous gas'],['radiant','Radiant white / cyan'],['ribbons','Electric-blue ribbons']],diskPalette:[['physical','Physical emission palette'],['artistic','Artistic · chosen color'],['rainbow','Rainbow · artistic']],jetStructure:[['steady','Continuous outflow'],['knots','Bright knots'],['helix','Helical filaments']]};
export function installAttachmentControls(api){
 const mount=document.createElement('section');mount.className='stellar-controls attachment-controls';mount.hidden=true;api.container.prepend(mount);
 const select=(key,label)=>`<label class="field-label" for="attachment-${key}">${label}</label><select id="attachment-${key}">${choices[key].map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}</select>`;
 const slider=(key,label,min,max,step)=>`<div class="stellar-range"><div class="range-header"><label for="attachment-${key}">${label}</label><output id="attachment-${key}-value"></output></div><input id="attachment-${key}" type="range" min="${min}" max="${max}" step="${step}"></div>`;
 mount.innerHTML=`<h4 id="attachment-title">ATTACHED FLOW</h4><p class="control-note" id="attachment-context"></p><label class="field-label" for="attachment-radiusMeters" id="attachment-radiusLabel">OUTER RADIUS · METERS</label><input id="attachment-radiusMeters" type="number" min="0.01" max="1e15" step="any"><label class="field-label" for="attachment-size">SIZE · LOGARITHMIC</label><input id="attachment-size" type="range" min="-2" max="15" step=".01"><div id="attachment-disc">${select('diskStyle','COMPOSITION / APPEARANCE')}${select('diskPalette','COLOR MODEL')}${slider('diskThickness','Thickness',.15,6,.05)}${slider('diskDensity','Optical density',0,4,.05)}</div><div id="attachment-jets">${select('jetStructure','PLASMA STRUCTURE')}${slider('jetSpread','Opening spread',.15,5,.05)}${slider('jetIntensity','Brightness',0,4,.05)}</div><label class="color-line" for="attachment-color"><span>Flow color</span><input id="attachment-color" type="color" value="#9cdcff"></label><p class="control-note">The flow follows its parent’s position and spin axis. Palettes and plasma structure are illustrative; spectral views apply their emission response.</p>`;
 const $=id=>mount.querySelector('#attachment-'+id);let selected=null,pending=null,raf=0;
 function patch(values){if(!selected)return;const renderer=api.renderer();pending={...(pending?.id===selected&&pending.renderer===renderer&&pending.sceneId===renderer?.sceneId?pending:{}),id:selected,renderer,sceneId:renderer?.sceneId,...values};if(raf)return;raf=requestAnimationFrame(()=>{raf=0;const edit=pending;pending=null;if(!edit||edit.id!==selected||edit.renderer!==api.renderer()||edit.sceneId!==api.renderer()?.sceneId)return;const {id,renderer,sceneId,...properties}=edit;renderer.updateObject?.(id,properties);api.changed();update(id);});}
 for(const key of Object.keys(choices))$(key).addEventListener('change',()=>patch({[key]:$(key).value}));
 for(const key of ['diskThickness','diskDensity','jetSpread','jetIntensity'])$(key).addEventListener('input',()=>patch({[key]:Number($(key).value)}));
 $('color').addEventListener('input',()=>patch({color:$('color').value}));$('color').addEventListener('change',()=>patch({color:$('color').value}));
 $('size').addEventListener('input',()=>patch({radiusMeters:10**Number($('size').value),scale:1}));$('radiusMeters').addEventListener('change',()=>{const value=Number($('radiusMeters').value);if(Number.isFinite(value)&&value>0)patch({radiusMeters:Math.max(.01,Math.min(1e15,value)),scale:1});else{const object=api.renderer()?.objects?.find(o=>o.id===selected);$('radiusMeters').value=object?.radiusMeters||1;}});
 function update(id){
  const r=api.renderer(),object=r?.objects?.find(o=>o.id===id),attached=['disk','jets'].includes(object?.type);selected=attached?id:null;mount.hidden=!attached;
  const scale=document.getElementById('editScale'),scaleLabel=document.querySelector('label[for="editScale"]');if(scale)scale.hidden=attached;if(scaleLabel?.closest('.range-header'))scaleLabel.closest('.range-header').hidden=attached;
  if(!attached)return;for(const id of ['physicalOrbitProperties','orbitalPlacement','localPlacement']){const el=document.getElementById(id);if(el)el.hidden=true;}
  const disc=object.type==='disk',parent=r.getObjectTree?.().find(n=>n.id===object.parentId);$('title').textContent=disc?'ACCRETION DISC':'POLAR JETS';$('context').textContent=`Attached to ${parent?.label||'the parent object'}. Edit its material and extent here.`;$('disc').hidden=!disc;$('jets').hidden=disc;$('radiusLabel').textContent=disc?'OUTER RADIUS · METERS':'JET EXTENT · METERS';
  const radius=(object.radiusMeters||1)*(object.scale||1);for(const [key,value] of Object.entries({radiusMeters:radius,size:Math.log10(Math.max(.01,radius)),diskStyle:object.diskStyle||'thermal',diskPalette:object.diskPalette||'physical',jetStructure:object.jetStructure||'steady',color:object.color||'#9cdcff',diskThickness:object.diskThickness??1,diskDensity:object.diskDensity??1,jetSpread:object.jetSpread??1,jetIntensity:object.jetIntensity??1})){const node=$(key);if(document.activeElement!==node)node.value=value;const output=$(''+key+'-value');if(output)output.textContent=Number(value).toFixed(2)+'×';}
 }
 return{update,dispose(){if(raf)cancelAnimationFrame(raf);pending=null;update(null);mount.remove();}};
}
